func(c *tsCollection)put(key,value tsValue){hash:=tsCollectionHash(key);if i,ok:=c.index[hash];ok{c.entries[i].value=value;return};if key.kind==tsNumberKind&&key.number==0{key.number=0};c.index[hash]=len(c.entries);c.entries=append(c.entries,tsCollectionEntry{key,value,true})}
func tsNewCollection(set bool,args ...tsValue)tsValue{c:=&tsCollection{set:set,index:map[tsCollectionKey]int{}};source:=tsArg(args,0);if !tsNullish(source){it:=tsIterate(source);for it.next(){if set{c.put(it.value,it.value)}else{pair:=it.value;if tsIsPrimitiveValue(pair){panic("Map entry must be an object")};c.put(tsGet(pair,tsNumberValue(0)),tsGet(pair,tsNumberValue(1)))}}};return tsCollectionValue(c)}
func(c *tsCollection)iterator(mode string)*tsIterator{index:=0;done:=false;return &tsIterator{pull:func()(tsValue,bool){if done{return tsU,false};for index<len(c.entries){entry:=c.entries[index];index++;if !entry.live{continue};switch mode{case "keys":return entry.key,true;case "values":if c.set{return entry.key,true};return entry.value,true;default:value:=entry.value;if c.set{value=entry.key};return tsArrayValue(&tsArray{values:[]tsValue{entry.key,value}}),true}};done=true;return tsU,false}}}
func tsCollectionGet(value tsValue,name string)tsValue{c:=(*tsCollection)(value.ref);if item,ok:=c.properties[name];ok{return item};if name=="size"{return tsNumberValue(float64(len(c.index)))};switch name{case "keys","values","entries":return tsFunc(func(args ...tsValue)tsValue{return tsIteratorValueReference(c.iterator(name))});case "get":if c.set{return tsU};return tsFunc(func(args ...tsValue)tsValue{if i,ok:=c.index[tsCollectionHash(tsArg(args,0))];ok{return c.entries[i].value};return tsU});case "has":return tsFunc(func(args ...tsValue)tsValue{_,ok:=c.index[tsCollectionHash(tsArg(args,0))];return tsBooleanValue(ok)});case "set","add":if (name=="add")!=c.set{return tsU};return tsFunc(func(args ...tsValue)tsValue{key:=tsArg(args,0);item:=tsArg(args,1);if c.set{item=key};c.put(key,item);return value});case "delete":return tsFunc(func(args ...tsValue)tsValue{hash:=tsCollectionHash(tsArg(args,0));i,ok:=c.index[hash];if ok{delete(c.index,hash);c.entries[i]=tsCollectionEntry{}};return tsBooleanValue(ok)});case "clear":return tsFunc(func(args ...tsValue)tsValue{clear(c.index);clear(c.entries);return tsU});case "forEach":return tsFunc(func(args ...tsValue)tsValue{callback:=tsArg(args,0);if callback.kind!=tsFunctionKind{panic("Callback must be callable")};for i:=0;i<len(c.entries);i++{entry:=c.entries[i];if entry.live{item:=entry.value;if c.set{item=entry.key};tsCall(callback,item,entry.key,value)}};return tsU})};if c.set{return tsSetMethod(value,name)};return tsU}
