const SetRuntime = `
func tsSetMethod(value tsValue,name string)tsValue{switch name{case "union","intersection","difference","symmetricDifference","isSubsetOf","isSupersetOf","isDisjointFrom":default:return tsU};return tsFunc(func(args ...tsValue)tsValue{self:=(*tsCollection)(value.ref);other:=tsArg(args,0);size:=tsNumber(tsToPrimitive(tsGet(other,tsStringReference(tsStringUTF8("size")))));if math.IsNaN(size)||size<0{panic("Invalid set-like size")};size=math.Trunc(size);has:=tsGet(other,tsStringReference(tsStringUTF8("has")));keys:=tsGet(other,tsStringReference(tsStringUTF8("keys")));if has.kind!=tsFunctionKind||keys.kind!=tsFunctionKind{panic("Expected a set-like object")};out:=&tsCollection{set:true,index:map[tsCollectionKey]int{}};copySelf:=func(){for _,entry:=range self.entries{if entry.live{out.put(entry.key,entry.key)}}};remove:=func(key tsValue){hash:=tsCollectionHash(key);if i,ok:=out.index[hash];ok{delete(out.index,hash);out.entries[i]=tsCollectionEntry{}}};contains:=func(key tsValue)bool{return tsTruthy(tsCall(has,key))};switch name{case "union":copySelf();it:=tsIterate(tsCall(keys));for it.next(){out.put(it.value,it.value)};case "intersection":if float64(len(self.index))<=size{for i:=0;i<len(self.entries);i++{entry:=self.entries[i];if entry.live&&contains(entry.key){out.put(entry.key,entry.key)}}}else{it:=tsIterate(tsCall(keys));for it.next(){if _,ok:=self.index[tsCollectionHash(it.value)];ok{out.put(it.value,it.value)}}};case "difference":copySelf();if float64(len(self.index))<=size{for i:=0;i<len(self.entries);i++{entry:=self.entries[i];if entry.live&&contains(entry.key){remove(entry.key)}}}else{it:=tsIterate(tsCall(keys));for it.next(){remove(it.value)}};case "symmetricDifference":copySelf();it:=tsIterate(tsCall(keys));for it.next(){if _,ok:=self.index[tsCollectionHash(it.value)];ok{remove(it.value)}else{out.put(it.value,it.value)}};case "isSubsetOf":if float64(len(self.index))>size{return tsBooleanValue(false)};for i:=0;i<len(self.entries);i++{entry:=self.entries[i];if entry.live&&!contains(entry.key){return tsBooleanValue(false)}};return tsBooleanValue(true);case "isSupersetOf":if float64(len(self.index))<size{return tsBooleanValue(false)};it:=tsIterate(tsCall(keys));for it.next(){if _,ok:=self.index[tsCollectionHash(it.value)];!ok{return tsBooleanValue(false)}};return tsBooleanValue(true);case "isDisjointFrom":if float64(len(self.index))<=size{for i:=0;i<len(self.entries);i++{entry:=self.entries[i];if entry.live&&contains(entry.key){return tsBooleanValue(false)}}}else{it:=tsIterate(tsCall(keys));for it.next(){if _,ok:=self.index[tsCollectionHash(it.value)];ok{return tsBooleanValue(false)}}};return tsBooleanValue(true)};return tsCollectionValue(out)})}
`
